function areaOf(shape, a, b) {
  switch (shape.toLowerCase()) {
    case "square":
      return a * a;
    case "rectangle":
      return a * b;
    case "circle": {
      const r = a;
      return +(Math.PI * r * r).toFixed(2);
    }
    default:
      return "Sorry the shape is not available";
  }
}
console.log(areaOf("Square", 5));
console.log(areaOf("rectangle", 5, 10));
console.log(areaOf("circle", 2));
console.log(areaOf("triangle", 1));

const score = 99;
console.log(score >= 60 ? "Pass" : "Fail");

function voteStatus(age, isCitizen, isRegistered) {
  if (age < 18) return "Not eligible (younger)";
  if (!isCitizen) return "Not eligible due to citizenship status";
  if (!isRegistered) return "Not eligible due to registration status";
  return "You are eligible to vote";
}
console.log(voteStatus(19, true, true));
console.log(voteStatus(19, false, true));
console.log(voteStatus(16, true, true));

for (let i = 1; i <= 5; i++) console.log(`5 * ${i} = ${5 * i}`);

let sum = 0;
for (let n = 1; n <= 10; n++) sum += n;
console.log("sum 1..10 =", sum);

function isPrime(num) {
  if (num < 2) return false;
  for (let i = 2; i * i <= num; i++) {
    if (num % i === 0) return false;
  }
  return true;
}
console.log(isPrime(13), isPrime(15));

for (let i = 1; i <= 4; i++) {
  let row = "";
  for (let j = 1; j <= i; j++) row += "* ";
  console.log(row.trim());
}

for (let i = 1; i <= 6; i++) {
  if (i === 2) continue;
  if (i === 5) break;
  console.log("i =", i);
}

outer: for (let a = 1; a <= 3; a++) {
  for (let b = 1; b <= 3; b++) {
    if (a * b === 4) break outer;
    console.log(a, b);
  }
}

const fruits = ["apple", "orange", "mango"];
for (const item of fruits) console.log("of:", item);
for (const idx in fruits) console.log("in:", idx, typeof idx);
fruits.forEach((item, i) => console.log("forEach:", i, item));

const person = { name: "Asha", age: 25 };
for (const key in person) console.log(key, "=", person[key]);
for (const [k, v] of Object.entries(person)) console.log(k, v);

try {
  for (const x of person) console.log(x);
} catch (e) {
  console.log(e.constructor.name, "-", e.message);
}
